// Reads Your settings and Your customers, checks them, and works out which addresses still need to
// be located. Each address is looked up once and remembered in workflow static data, which n8n keeps
// only while the workflow is published.
const s = $('Your settings').first().json;
const st = $getWorkflowStaticData('global');
st.geo = st.geo || {};

const phone = v => {
  const raw = String(v || '').trim();
  const digits = raw.replace(/\D/g, '');
  if (!digits) return '';
  if (raw.startsWith('+') && digits.length >= 8 && digits.length <= 15) return '+' + digits;
  if (digits.length === 10) return '+1' + digits;
  if (digits.length === 11 && digits.startsWith('1')) return '+' + digits;
  return 'bad';
};
const num = (v, d) => (v === '' || v === null || v === undefined || isNaN(Number(v))) ? d : Number(v);
const bool = (v, d) => {
  if (v === undefined || v === null || v === '') return d;
  return !['false', 'no', 'off', '0'].includes(String(v).trim().toLowerCase());
};
const hhmm = (v, d) => /^([01]?\d|2[0-3]):[0-5]\d$/.test(String(v || '').trim()) ? String(v).trim() : d;
const addrKey = a => String(a || '').toLowerCase().replace(/[.,#]/g, ' ').replace(/\s+/g, ' ').trim();

const business_number = phone(s.business_number);
const owner_cell = phone(s.owner_cell);
if (!business_number || !owner_cell || business_number === 'bad' || owner_cell === 'bad') {
  throw new Error('Your settings: business_number and owner_cell must both be filled in with full phone numbers: a plus sign, the country code, then the number.');
}
const timezone = String(s.timezone || 'America/New_York').trim();
if (!DateTime.now().setZone(timezone).isValid) {
  throw new Error('Your settings: "' + timezone + '" is not a time zone n8n knows. Use a name like America/New_York.');
}
const replay = String(s.replay_spc_day || '').trim();
if (replay && !/^\d{6}$/.test(replay)) {
  throw new Error('Your settings: replay_spc_day must be blank, or a past storm day written YYMMDD, like 250519.');
}
const outreach_url = String(s.outreach_url || '').trim();
if (outreach_url && !/^https?:\/\/\S+$/.test(outreach_url)) {
  throw new Error('Your settings: outreach_url must be blank, or the full address of the outreach workflow\'s request webhook.');
}
const DEFAULT_WARNINGS = 'Hard Freeze Warning, Freeze Warning, Extreme Cold Warning, Extreme Heat Warning, Excessive Heat Warning, High Wind Warning, Flash Flood Warning, Flood Warning, Ice Storm Warning, Winter Storm Warning, Hurricane Warning, Tropical Storm Warning';
const warnings = String(s.warnings === undefined ? DEFAULT_WARNINGS : s.warnings)
  .split(/[,\n]+/).map(x => x.trim()).filter(Boolean);

const cfg = {
  business_name: String(s.business_name || 'your business').trim(),
  business_number, owner_cell, timezone,
  contact_email: String(s.contact_email || '').trim(),
  radius_miles: Math.min(50, Math.max(0.25, num(s.radius_miles, 3))),
  watch_hail: bool(s.watch_hail, true),
  hail_min_inches: Math.max(0.25, num(s.hail_min_inches, 1)),
  watch_wind: bool(s.watch_wind, true),
  wind_min_mph: Math.max(0, num(s.wind_min_mph, 58)),
  wind_damage_reports: bool(s.wind_damage_reports, true),
  warnings,
  warnings_lower: warnings.map(w => w.toLowerCase()),
  quiet_start: hhmm(s.quiet_start, '21:00'),
  quiet_end: hhmm(s.quiet_end, '07:00'),
  max_names: Math.max(1, Math.min(30, num(s.max_names, 8))),
  lookups_per_run: Math.max(1, Math.min(100, num(s.lookups_per_run, 25))),
  outreach_url,
  outreach_key: String(s.outreach_key || '').trim(),
  hail_message: String(s.hail_message || '').trim(),
  wind_message: String(s.wind_message || '').trim(),
  warning_message: String(s.warning_message || '').trim(),
  replay,
};
cfg.user_agent = '(' + cfg.business_name.replace(/[()]/g, '') + ' weather watch, ' + (cfg.contact_email || 'n8n template') + ')';
if (cfg.outreach_url && !cfg.outreach_key) {
  throw new Error('Your settings: outreach_url is set, so outreach_key must match the request_key in the outreach workflow.');
}

// Your customers: either one field called customers with one line each
//   name | phone | email | address | ok to text (yes/no)
// or rows from a sheet or database with columns name, phone, email, address, ok_to_text (lat and lon optional).
const src = $('Your customers').all().map(i => i.json);
let rows = [];
const problems = [];
if (src.length === 1 && typeof src[0].customers === 'string') {
  src[0].customers.split(/\r?\n/).forEach((line, n) => {
    const t = line.trim();
    if (!t || t.startsWith('#')) return;
    const p = t.split('|').map(x => x.trim());
    if (p.length < 4) { problems.push('Line ' + (n + 1) + ' needs name | phone | email | address: "' + t.slice(0, 60) + '"'); return; }
    rows.push({ name: p[0], phone: p[1], email: p[2], address: p[3], ok_to_text: p[4] });
  });
} else {
  rows = src;
}

const customers = [];
const seen = {};
for (const r of rows) {
  const name = String(r.name || '').trim();
  const address = String(r.address || '').trim();
  if (!address) { if (name) problems.push(name + ' has no address, so it cannot be matched to the weather.'); continue; }
  const key = addrKey(address);
  const ph = phone(r.phone);
  if (ph === 'bad') problems.push(name + ': "' + r.phone + '" is not a phone number, so they can be matched but not texted.');
  const lat = r.lat === '' || r.lat === undefined ? NaN : Number(r.lat);
  const lon = r.lon === '' || r.lon === undefined ? NaN : Number(r.lon);
  const c = {
    key, name: name || address, address,
    phone: ph === 'bad' ? '' : ph,
    email: /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(r.email || '').trim()) ? String(r.email).trim() : '',
    ok_to_text: bool(r.ok_to_text, false),
    given: isFinite(lat) && isFinite(lon) && Math.abs(lat) <= 90 && Math.abs(lon) <= 180 ? { lat, lon } : null,
  };
  if (seen[key + '|' + c.phone]) continue;
  seen[key + '|' + c.phone] = true;
  customers.push(c);
}
if (!customers.length) {
  throw new Error('Your customers: no customers with an address were found. Add one line per customer: name | phone | email | address | ok to text.');
}

// Addresses not looked up yet. A given lat/lon still needs its weather zone looked up once.
const need = [];
const queued = {};
for (const c of customers) {
  const g = st.geo[c.key];
  if (g && (g.found || g.tries >= 1)) continue;
  if (queued[c.key]) continue;
  queued[c.key] = true;
  need.push({ key: c.key, address: c.address, given: c.given });
  if (need.length >= cfg.lookups_per_run) break;
}

return [{ json: { cfg, customers, need, problems } }];

// Saves what the two lookups found for each new address: its latitude and longitude from the US
// Census geocoder (or the ones in your list), and its National Weather Service forecast zone and
// county, which is how weather warnings are matched. An address the geocoder cannot find is tried once
// and then named in the next text, so you can fix it in your list.
const st = $getWorkflowStaticData('global');
st.geo = st.geo || {};
const asked = $('One item per address').all();
const census = $('Look up the address').all();
const zones = $input.all();
const now = new Date().toISOString();
const code = u => String(u || '').split('/').pop();
let found = 0;
const missing = [];
asked.forEach((a, i) => {
  const q = a.json;
  const res = ((census[i] || {}).json || {}).result || {};
  const m = (res.addressMatches || [])[0];
  let lat, lon, state = '';
  if (q.given) { lat = q.given.lat; lon = q.given.lon; }
  else if (m && m.coordinates) { lat = Number(m.coordinates.y); lon = Number(m.coordinates.x); state = (m.addressComponents || {}).state || ''; }
  if (!isFinite(lat) || !isFinite(lon)) {
    st.geo[q.key] = { found: false, tries: ((st.geo[q.key] || {}).tries || 0) + 1, at: now };
    missing.push(q.address);
    return;
  }
  // The Weather Service answers with geo+json, which some n8n versions hand over as text.
  let zj = (zones[i] || {}).json || {};
  if (!zj.properties && typeof zj.data === 'string') { try { zj = JSON.parse(zj.data); } catch (e) { zj = {}; } }
  const p = zj.properties || {};
  const rel = ((p.relativeLocation || {}).properties) || {};
  st.geo[q.key] = {
    found: true,
    lat: Math.round(lat * 1e5) / 1e5,
    lon: Math.round(lon * 1e5) / 1e5,
    state: state || rel.state || '',
    zone: code(p.forecastZone),
    county: code(p.county),
    near: rel.city ? rel.city + (rel.state ? ', ' + rel.state : '') : '',
    at: now,
  };
  found++;
});
return [{ json: { found, missing } }];

// Lists the public reports to read this round. Storm reports come from the NOAA Storm Prediction
// Center as CSV files, one per storm day (a day runs noon to noon UTC). Weather warnings come from the
// National Weather Service for the states your customers are in. Nothing here needs an account.
const { cfg, customers } = $('Read your settings and customers').first().json;
const geo = ($getWorkflowStaticData('global').geo) || {};
const base = 'https://www.spc.noaa.gov/climo/reports/';
const items = [];
const days = cfg.replay ? [cfg.replay] : ['today', 'yesterday'];
for (const d of days) {
  const file = k => base + (cfg.replay ? d + '_rpts_' + k + '.csv' : d + '_' + k + '.csv');
  if (cfg.watch_hail) items.push({ kind: 'hail', day: d, url: file('hail') });
  if (cfg.watch_wind) items.push({ kind: 'wind', day: d, url: file('wind') });
}
const states = [...new Set(customers.map(c => geo[c.key]).filter(g => g && g.found && /^[A-Z]{2}$/.test(g.state || '')).map(g => g.state))].sort();
if (!cfg.replay && cfg.warnings.length && states.length) {
  items.push({ kind: 'warning', day: 'now', url: 'https://api.weather.gov/alerts/active?status=actual&area=' + states.join(',') });
}
if (!items.length) {
  throw new Error('Your settings: watch_hail and watch_wind are both off and warnings is empty, so there is nothing to watch.');
}
return items.map(json => ({ json }));

// Reads the storm reports and warnings, finds which of your customers they touch, and writes one
// text. Each customer is named once per storm day for hail or wind, and once per warning, so the
// same storm does not keep texting you. Its memory is n8n workflow static data.
const { cfg, customers, problems } = $('Read your settings and customers').first().json;
const st = $getWorkflowStaticData('global');
st.geo = st.geo || {};
st.told = st.told || {};
st.fail = st.fail || {};
st.problemsTold = st.problemsTold || {};
st.held = st.held || [];
st.unsent = st.unsent || [];

const tz = cfg.timezone;
const now = DateTime.now().setZone(tz);
const plans = $('Plan the checks').all().map(i => i.json);
const got = $input.all().map(i => i.json);

// ---------- helpers ----------
const miles = (a, b) => {
  const R = 3958.8, rad = x => x * Math.PI / 180;
  const dLat = rad(b.lat - a.lat), dLon = rad(b.lon - a.lon);
  const h = Math.sin(dLat / 2) ** 2 + Math.cos(rad(a.lat)) * Math.cos(rad(b.lat)) * Math.sin(dLon / 2) ** 2;
  return 2 * R * Math.asin(Math.sqrt(h));
};
const pretty = p => /^\+1\d{10}$/.test(p) ? '(' + p.slice(2, 5) + ') ' + p.slice(5, 8) + '-' + p.slice(8) : p;
const fmtMi = d => (d < 0.1 ? 'under 0.1' : d.toFixed(1)) + ' mi';
const fmtTime = dt => {
  const t = dt.setZone(tz);
  return t.hasSame(now, 'day') ? t.toFormat('h:mm a') : t.toFormat('ccc h:mm a');
};
const fill = (tpl, vals) => String(tpl).replace(/\{(\w+)\}/g, (m, k) => (k in vals ? vals[k] : m));
const inQuiet = t => {
  const [sh, sm] = cfg.quiet_start.split(':').map(Number), [eh, em] = cfg.quiet_end.split(':').map(Number);
  const m = t.hour * 60 + t.minute, a = sh * 60 + sm, b = eh * 60 + em;
  return a === b ? false : a < b ? (m >= a && m < b) : (m >= a || m < b);
};
// A storm day starts at 12:00 UTC. "today" is the day that started most recently.
const dayStart = day => {
  if (/^\d{6}$/.test(day)) return DateTime.fromObject({ year: 2000 + Number(day.slice(0, 2)), month: Number(day.slice(2, 4)), day: Number(day.slice(4, 6)), hour: 12 }, { zone: 'utc' });
  let d = DateTime.now().setZone('utc').set({ hour: 12, minute: 0, second: 0, millisecond: 0 });
  if (DateTime.now().setZone('utc').hour < 12) d = d.minus({ days: 1 });
  return day === 'yesterday' ? d.minus({ days: 1 }) : d;
};
const parseSpc = (text, kind, day) => {
  const lines = String(text || '').split(/\r?\n/);
  if (!/^Time,(Size|Speed),Location,County,State,Lat,Lon/.test(lines[0] || '')) return null;
  const start = dayStart(day);
  const out = [];
  for (const line of lines.slice(1)) {
    if (!line.trim()) continue;
    const p = line.split(',');
    if (p.length < 7) continue;
    const hhmm = p[0].padStart(4, '0');
    const h = Number(hhmm.slice(0, 2)), mi = Number(hhmm.slice(2));
    if (!(h >= 0 && h < 24 && mi >= 0 && mi < 60)) continue;
    let when = start.set({ hour: h, minute: mi });
    if (h < 12) when = when.plus({ days: 1 });
    const lat = Number(p[5]), lon = Number(p[6]);
    if (!isFinite(lat) || !isFinite(lon)) continue;
    const raw = p[1].trim();
    const value = kind === 'hail' ? Number(raw) / 100 : (/^\d+$/.test(raw) ? Number(raw) : null);
    out.push({ kind, when, value, place: p[2].trim(), county: p[3].trim(), state: p[4].trim(), lat, lon, stormDay: start.toISODate() });
  }
  return out;
};

// ---------- located customers ----------
const located = customers.map(c => ({ c, g: st.geo[c.key] })).filter(x => x.g && x.g.found);
const notFound = customers.filter(c => st.geo[c.key] && !st.geo[c.key].found).map(c => c.name + ' (' + c.address + ')');
const waiting = customers.filter(c => !st.geo[c.key]).length;

// ---------- read each source ----------
const reports = { hail: [], wind: [] };
const warnings = [];
const sourceNotes = [];
const label = { hail: 'NOAA hail reports', wind: 'NOAA wind reports', warning: 'National Weather Service warnings' };
const bad = {};
plans.forEach((p, i) => {
  const text = (got[i] || {}).data;
  let ok = false;
  if (p.kind === 'warning') {
    try {
      const j = typeof text === 'string' ? JSON.parse(text) : text;
      if (j && Array.isArray(j.features)) { warnings.push(...j.features.map(f => f.properties || {})); ok = true; }
    } catch (e) { ok = false; }
  } else {
    const r = parseSpc(text, p.kind, p.day);
    if (r) { reports[p.kind].push(...r); ok = true; }
  }
  bad[p.kind] = bad[p.kind] || !ok;
});
Object.keys(bad).forEach(k => {
  if (bad[k]) {
    st.fail[k] = (st.fail[k] || 0) + 1;
    if (st.fail[k] === 12) sourceNotes.push('Could not read ' + label[k] + ' on the last 12 checks. Still trying.');
  } else {
    if ((st.fail[k] || 0) >= 12) sourceNotes.push(label[k] + ' can be read again.');
    st.fail[k] = 0;
  }
});

// ---------- hail and wind near customers ----------
const replay = !!cfg.replay;
const hits = { hail: {}, wind: {} };
for (const kind of ['hail', 'wind']) {
  for (const r of reports[kind]) {
    if (kind === 'hail' && !(r.value >= cfg.hail_min_inches)) continue;
    if (kind === 'wind' && !(r.value === null ? cfg.wind_damage_reports : r.value >= cfg.wind_min_mph)) continue;
    for (const { c, g } of located) {
      const d = miles(g, r);
      if (d > cfg.radius_miles) continue;
      const tellKey = c.key + '|' + kind + '|' + r.stormDay;
      if (!replay && st.told[tellKey]) continue;
      const cur = hits[kind][tellKey];
      const better = !cur || (r.value || 0) > (cur.r.value || 0) || ((r.value || 0) === (cur.r.value || 0) && d < cur.d);
      if (better) hits[kind][tellKey] = { c, r, d, tellKey };
    }
  }
}

// ---------- warnings over customers ----------
const warnHits = {};
for (const w of warnings) {
  const event = String(w.event || '');
  if (!cfg.warnings_lower.includes(event.toLowerCase())) continue;
  if (w.messageType === 'Cancel' || w.status !== 'Actual') continue;
  const ugc = ((w.geocode || {}).UGC) || [];
  const start = DateTime.fromISO(w.onset || w.effective || w.sent || '', { zone: tz });
  const until = DateTime.fromISO(w.ends || w.expires || '', { zone: tz });
  if (until.isValid && until < now) continue;
  for (const { c, g } of located) {
    if (!(ugc.includes(g.zone) || ugc.includes(g.county))) continue;
    const tellKey = c.key + '|warn:' + event.toLowerCase() + '|' + (start.isValid ? start.toISODate() : now.toISODate());
    if (st.told[tellKey]) continue;
    const grp = warnHits[event] = warnHits[event] || { event, until: null, areas: new Set(), list: {} };
    if (until.isValid && (!grp.until || until > grp.until)) grp.until = until;
    String(w.areaDesc || '').split(';').map(x => x.trim()).filter(Boolean).forEach(a => grp.areas.add(a));
    grp.list[tellKey] = { c, tellKey };
  }
}

// ---------- write it up ----------
const DEFAULT_MSG = {
  hail: 'Hi {first_name}, this is {business_name}. Hail up to {size} was reported near your home on {date}. Hail damage is easy to miss from the ground. Want us to take a free look? Reply YES and we will set up a time.',
  wind: 'Hi {first_name}, this is {business_name}. Damaging wind was reported near your home on {date}. If you have noticed anything loose or damaged, reply here and we will take a look.',
  warning: 'Hi {first_name}, this is {business_name}. A {event} is in effect for your area until {until}. If anything needs attention before or after, reply here and we will help.',
};
const blocks = [];
const requests = [];
const toldNow = [];
const listNames = (arr, fmt) => {
  const shown = arr.slice(0, cfg.max_names).map(fmt);
  if (arr.length > cfg.max_names) shown.push('plus ' + (arr.length - cfg.max_names) + ' more');
  return shown;
};
for (const kind of ['hail', 'wind']) {
  const arr = Object.values(hits[kind]).sort((a, b) => (b.r.value || 0) - (a.r.value || 0) || a.d - b.d);
  if (!arr.length) continue;
  const top = arr[0].r;
  const dayText = top.when.setZone(tz).toFormat('ccc LLL d');
  const head = kind === 'hail'
    ? 'Hail up to ' + top.value.toFixed(2) + ' in reported within ' + cfg.radius_miles + ' mi of ' + arr.length + ' past customer' + (arr.length > 1 ? 's' : '') + ':'
    : 'Damaging wind reported within ' + cfg.radius_miles + ' mi of ' + arr.length + ' past customer' + (arr.length > 1 ? 's' : '') + ':';
  const lines = listNames(arr, h => '- ' + h.c.name + (h.c.phone ? ' ' + pretty(h.c.phone) : '') + ', ' + fmtMi(h.d) + ' from ' +
    (kind === 'hail' ? h.r.value.toFixed(2) + ' in hail' : (h.r.value ? h.r.value + ' mph wind' : 'a wind damage report')) +
    ' at ' + fmtTime(h.r.when) + ' (' + h.r.place + ', ' + h.r.state + ')');
  blocks.push([head, ...lines].join('\n'));
  requests.push({
    title: (kind === 'hail' ? 'Hail' : 'Wind damage') + ' near ' + arr.length + ' past customer' + (arr.length > 1 ? 's' : '') + ' (' + dayText + ')',
    summary: [head, ...lines].join('\n'),
    message: fill(cfg[kind + '_message'] || DEFAULT_MSG[kind], { business_name: cfg.business_name, date: dayText, size: kind === 'hail' ? top.value.toFixed(2) + ' inch' : '' }),
    customers: arr.map(h => ({ name: h.c.name, phone: h.c.phone, email: h.c.email, ok_to_text: h.c.ok_to_text, detail: fmtMi(h.d) })),
    source: 'weather-' + kind,
  });
  arr.forEach(h => toldNow.push(h.tellKey));
}
for (const grp of Object.values(warnHits)) {
  const arr = Object.values(grp.list).sort((a, b) => a.c.name.localeCompare(b.c.name));
  if (!arr.length) continue;
  const untilText = grp.until ? (grp.until.hasSame(now, 'day') ? grp.until.toFormat('h:mm a') + ' today' : grp.until.toFormat('ccc LLL d, h:mm a')) : 'further notice';
  const areas = [...grp.areas];
  const head = grp.event + ' until ' + untilText + ' covers ' + arr.length + ' past customer' + (arr.length > 1 ? 's' : '') +
    (areas.length ? ' (' + areas.slice(0, 3).join('; ') + (areas.length > 3 ? '; and more' : '') + ')' : '') + ':';
  const names = listNames(arr, h => h.c.name).join(', ');
  blocks.push(head + '\n' + names);
  requests.push({
    title: grp.event + ': ' + arr.length + ' past customer' + (arr.length > 1 ? 's' : ''),
    summary: head + '\n' + names,
    message: fill(cfg.warning_message || DEFAULT_MSG.warning, { business_name: cfg.business_name, event: grp.event, until: untilText, date: now.toFormat('ccc LLL d') }),
    customers: arr.map(h => ({ name: h.c.name, phone: h.c.phone, email: h.c.email, ok_to_text: h.c.ok_to_text, detail: '' })),
    source: 'weather-warning',
  });
  arr.forEach(h => toldNow.push(h.tellKey));
}

// Things you need to fix, said once each.
const fixes = [];
const newProblems = problems.filter(p => !st.problemsTold[p]);
newProblems.forEach(p => { st.problemsTold[p] = now.toISO(); });
if (newProblems.length) fixes.push('Lines in your list I could not use: ' + newProblems.slice(0, 5).join(' / ') + (newProblems.length > 5 ? ' / plus ' + (newProblems.length - 5) + ' more' : ''));
const newMissing = notFound.filter(a => !st.problemsTold['nf:' + a]);
newMissing.forEach(a => { st.problemsTold['nf:' + a] = now.toISO(); });
if (newMissing.length) fixes.push('Addresses the geocoder could not find, so they are not watched: ' + newMissing.slice(0, 5).join('; ') + (newMissing.length > 5 ? '; plus ' + (newMissing.length - 5) + ' more' : '') + '. Fix the address or add lat and lon.');

const parts = [];
let justStarted = false;
if (!st.started) {
  justStarted = true;
  const watching = [];
  if (cfg.watch_hail) watching.push('hail ' + cfg.hail_min_inches + ' in and up');
  if (cfg.watch_wind) watching.push('wind ' + cfg.wind_min_mph + ' mph and up' + (cfg.wind_damage_reports ? ' or wind damage' : ''));
  if (cfg.warnings.length) watching.push(cfg.warnings.length + ' kinds of weather warnings');
  parts.push('Weather watch is on for ' + cfg.business_name + '. ' + customers.length + ' customers, ' + located.length + ' located' +
    (waiting ? ', ' + waiting + ' still to look up' : '') + '. Watching ' + watching.join(', ') + ', within ' + cfg.radius_miles + ' mi.');
  st.started = now.toISO();
}
const handOff = !!cfg.outreach_url;
if (!handOff) parts.push(...blocks);
parts.push(...fixes, ...sourceNotes);

// Remember who was named, so the same storm does not name them again.
if (!replay) toldNow.forEach(k => { st.told[k] = now.toISO(); });
const cutoff = now.minus({ days: 14 }).toISO();
Object.keys(st.told).forEach(k => { if (st.told[k] < cutoff) delete st.told[k]; });

let body = parts.join('\n\n');
if (body && !justStarted) body = 'Weather watch, ' + cfg.business_name + ':\n' + body;

// Quiet hours: hold the text for the morning. A text Twilio refused before goes again now, for up to
// five tries. The text being sent is kept as unsent until Twilio accepts it.
const tries = st.unsent.reduce((m, u) => Math.max(m, u.tries || 0), 0);
if (tries >= 5) st.unsent = [];
let send = false;
if (body && inQuiet(now)) {
  st.held.push(body);
  body = '';
} else if (!inQuiet(now)) {
  const out = [...st.unsent.map(u => u.body), ...st.held];
  if (body) out.push(body);
  st.held = [];
  body = out.join('\n\n---\n\n');
  if (body.length > 1500) body = body.slice(0, 1480) + '\n(cut short)';
  send = !!body;
  st.unsent = send ? [{ body, tries: (st.unsent.length ? tries : 0) + 1 }] : [];
}

return [{ json: { send, from: cfg.business_number, to: cfg.owner_cell, body, requests: handOff ? requests : [], outreach_url: cfg.outreach_url, outreach_key: cfg.outreach_key } }];

// Twilio took the text, so it is no longer waiting to be sent again. Anything added since (a handoff
// the outreach workflow did not take) stays for the next check.
const st = $getWorkflowStaticData('global');
st.unsent = (st.unsent || []).filter(u => !u.tries);
return [{ json: { delivered: true, sid: $json.sid } }];

// One item per group of customers (hail, wind, or one kind of warning), for the outreach workflow.
const m = $('Match to your customers').first().json;
return m.requests.map(r => ({ json: { url: m.outreach_url, body: { key: m.outreach_key, ...r } } }));

// The outreach workflow answers {"ok": true} when it has the request and is texting you for approval.
// If it did not, the summary is kept and texted to you directly on the next check, so a storm is never
// dropped silently.
const st = $getWorkflowStaticData('global');
st.unsent = st.unsent || [];
const sent = $('One item per request').all();
const answers = $input.all();
let ok = 0;
const failed = [];
sent.forEach((s, i) => {
  const a = (answers[i] || {}).json || {};
  if (a.ok === true) ok++;
  else failed.push(s.json.body);
});
for (const r of failed) {
  st.unsent.push({ body: 'The outreach workflow did not take this, so here it is directly:\n' + r.summary, tries: 0 });
}
return [{ json: { handed_off: ok, failed: failed.length } }];
